func schema_gpustack_api_worker_v1_InstanceTypeFlavorSpec(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "InstanceTypeFlavorSpec describes one pool aggregated from the ResourceFlavor notes. Its fields mirror the InstanceTypeSpec identity — accelerator/general group + acceleratable + manufacturer/product/family + memory/cores — so the catalog and an InstanceType read consistently. Which group fields are populated tracks instance-type-aware-cpu-manufacturer: with awareness off a generic pool carries GeneralGroup=\"generic\" and an accelerated pool only its AcceleratorGroup; with awareness on both carry the real CPU key in GeneralGroup.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"acceleratorGroup": {
						SchemaProps: spec.SchemaProps{
							Description: "AcceleratorGroup is the accelerator group (the acceleratable key) of an accelerated pool, e.g. \"nvidia-a10g\"; empty for a generic pool.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"acceleratable": {
						SchemaProps: spec.SchemaProps{
							Description: "Acceleratable reports whether the pool represents accelerated hardware; a generic (CPU-only) pool is false. It delimits generic from accelerated flavors.",
							Default:     false,
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
					"manufacturer": {
						SchemaProps: spec.SchemaProps{
							Description: "Manufacturer is the device (or CPU) manufacturer, e.g. \"nvidia\", \"generic\".",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"product": {
						SchemaProps: spec.SchemaProps{
							Description: "Product is the product name, e.g. \"NVIDIA A10G\"; empty for a generic pool.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"family": {
						SchemaProps: spec.SchemaProps{
							Description: "Family is the product family, e.g. \"ampere\"; empty for a generic pool.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"memory": {
						SchemaProps: spec.SchemaProps{
							Description: "Memory is the per-accelerator VRAM, e.g. \"24576Mi\"; empty for a generic pool.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"cores": {
						SchemaProps: spec.SchemaProps{
							Description: "Cores is the per-accelerator core count, e.g. \"9216\"; empty for a generic pool.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"generalGroup": {
						SchemaProps: spec.SchemaProps{
							Description: "GeneralGroup is the general(CPU) group of the pool: the real CPU key when instance-type-aware-cpu-manufacturer is on, or the \"generic\" sentinel for a collapsed (unaware) generic pool; empty for an accelerated pool when awareness is off.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
				},
				Required: []string{"acceleratable"},
			},
		},
	}
}

