func schema_gpustack_api_worker_v1alpha1_DeviceInterface(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "DeviceInterface describes one network interface of the worker.\n\nEnumeration is interface-first: the interface is the identity and its PCI device is resolved as an attribute, which is the inverse of walking the PCI bus and correlating back. An interface reached over a non-PCI interconnect is invisible to a PCI-rooted walk, and that is exactly the case this record must not lose — so every PCI field here is optional and their joint absence is a KIND of interface, not a hole in the record.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"name": {
						SchemaProps: spec.SchemaProps{
							Description: "Name is the kernel interface name, and is this interface's identity.",
							Default:     "",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"bus": {
						SchemaProps: spec.SchemaProps{
							Description: "Bus names the interconnect the interface was found on, so an interface with no PCI coordinates reports what it is instead of reading as a failed PCI lookup.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"pciBusId": {
						SchemaProps: spec.SchemaProps{
							Description: "PciBusID is the PCI bus ID of the interface. Absent for a non-PCI interface.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"pciRootId": {
						SchemaProps: spec.SchemaProps{
							Description: "PciRootID is the address of the OUTERMOST PCI BRIDGE above the interface, or the interface's own address when no bridge sits above it. Despite the name it is not a root complex, and reading it as one advertises closeness nobody measured. Absent for a non-PCI interface. It comes from the same walk the accelerator side uses, so the two values are comparable.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"pciSwitches": {
						VendorExtensible: spec.VendorExtensible{
							Extensions: spec.Extensions{
								"x-kubernetes-list-type": "atomic",
							},
						},
						SchemaProps: spec.SchemaProps{
							Description: "PciSwitches is the upstream PCI bridge/switch path, innermost first — the same coordinate DeviceTopology carries, so an accelerator and an interface can be compared without a translation layer. Absent for a non-PCI interface.",
							Type:        []string{"array"},
							Items: &spec.SchemaOrArray{
								Schema: &spec.Schema{
									SchemaProps: spec.SchemaProps{
										Default: "",
										Type:    []string{"string"},
										Format:  "",
									},
								},
							},
						},
					},
					"pciVendor": {
						SchemaProps: spec.SchemaProps{
							Description: "PciVendor and PciDevice are the raw hex PCI ids, deliberately not resolved to a model name: resolving one reads a host data file a minimal image may not carry, and a name that resolves on one worker but not another is worse than a hex id that always does.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"pciDevice": {
						SchemaProps: spec.SchemaProps{
							Description: "PciDevice is the raw hex PCI device id. See PciVendor.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"numaAffinity": {
						SchemaProps: spec.SchemaProps{
							Description: "NumaAffinity is the NUMA node the interface is attached to. Empty means UNKNOWN and is never normalised to node 0 — that would report an affinity nobody read.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"cpuAffinity": {
						SchemaProps: spec.SchemaProps{
							Description: "CpuAffinity is the CPU cores close to the interface. Empty means unknown.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"mtu": {
						SchemaProps: spec.SchemaProps{
							Description: "MTU is the link MTU. Zero means it was not read, not an MTU of zero — no operational interface reports zero, so the absent value carries no ambiguity.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"up": {
						SchemaProps: spec.SchemaProps{
							Description: "Up reports the interface's operational state.",
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
					"virtual": {
						SchemaProps: spec.SchemaProps{
							Description: "Virtual marks an interface with no device behind it (loopback, bridge, veth). Such an interface is RECORDED AND MARKED, never dropped: a worker whose only interface is a bridge must read as \"one virtual interface\", not as \"no interfaces\".",
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
					"rdma": {
						SchemaProps: spec.SchemaProps{
							Description: "RDMA reports that an RDMA device is bound to this interface. It says nothing about whether the link works — that is Link below, and the two differ on real hardware.",
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
					"rdmaDevice": {
						SchemaProps: spec.SchemaProps{
							Description: "RDMADevice is the bound RDMA device's name. Empty when RDMA is false.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"sriov": {
						SchemaProps: spec.SchemaProps{
							Description: "SRIOV reports that this interface is an SR-IOV physical function. It is a SEPARATE fact from the length of VirtualFunctions: \"a PF with zero VFs configured\" and \"not a PF at all\" are different states, and deriving the second from an empty VF list collapses them.",
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
					"virtualFunctions": {
						VendorExtensible: spec.VendorExtensible{
							Extensions: spec.Extensions{
								"x-kubernetes-list-type": "atomic",
							},
						},
						SchemaProps: spec.SchemaProps{
							Description: "VirtualFunctions are this physical function's virtual functions, NESTED here rather than listed as siblings: a PF with eight VFs is one entry with eight nested, never nine top-level entries. Ordered by bus id, so two consecutive reads are byte-identical.",
							Type:        []string{"array"},
							Items: &spec.SchemaOrArray{
								Schema: &spec.Schema{
									SchemaProps: spec.SchemaProps{
										Default: map[string]interface{}{},
										Ref:     ref(v1alpha1.DeviceInterfaceVirtualFunction{}.OpenAPIModelName()),
									},
								},
							},
						},
					},
					"link": {
						SchemaProps: spec.SchemaProps{
							Description: "Link is the result of verifying that this interface's RDMA link is usable. Nil when there is no RDMA link to verify.",
							Ref:         ref(v1alpha1.DeviceInterfaceLink{}.OpenAPIModelName()),
						},
					},
				},
				Required: []string{"name"},
			},
		},
		Dependencies: []string{
			v1alpha1.DeviceInterfaceLink{}.OpenAPIModelName(), v1alpha1.DeviceInterfaceVirtualFunction{}.OpenAPIModelName()},
	}
}

func schema_gpustack_api_worker_v1alpha1_DeviceInterfaceLink(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "DeviceInterfaceLink is the outcome of verifying that an RDMA-capable interface's link is actually usable.\n\nReporting and enforcement are separated by making the outcome an explicit state rather than a boolean: only Failed withholds the node's RDMA label, because \"we have no check for this interface\" must not be published as \"this worker has no RDMA\".",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"state": {
						SchemaProps: spec.SchemaProps{
							Description: "State is the verification outcome.\n\nPossible enum values:\n - `\"failed\"` indicates a check ran and the link is not usable. This is the only state that withholds the node's RDMA label, and it is never reached from a missing or unreadable file — an unreadable attribute is Unverified.\n - `\"ok\"` indicates the link was checked and verified.\n - `\"unverified\"` indicates the check reached no verdict: an attribute it needs was unreadable, the port directory could not be listed, or the RDMA tree is present and could not be read at all. There is no per-manufacturer checker to be missing — the check reads the RDMA subsystem's own port attributes and dispatches on nothing. It is REPORTED, and it does not withhold the node's RDMA label: a link we cannot interrogate must not silently exclude its worker from scheduling.",
							Default:     "",
							Type:        []string{"string"},
							Format:      "",
							Enum:        []interface{}{"failed", "ok", "unverified"},
						},
					},
					"reason": {
						SchemaProps: spec.SchemaProps{
							Description: "Reason carries the checker's own words, verbatim — including the attribute values it read. A non-ok state without a reason leaves the operator's actual question (\"why?\") unanswerable from the record alone.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"firstSeenTime": {
						SchemaProps: spec.SchemaProps{
							Description: "FirstSeenTime is when an ONGOING FAILED state was first observed. It is stable across passes for as long as the failure persists, and is cleared the moment the state is anything else. Refreshing it every pass would make \"how long has this been down?\" unanswerable, which is the question the field exists to answer.\n\nNil for both other states, `unverified` included: a state that reached no verdict has no outage for a clock to be the start of, so this is not \"the current non-ok state\" but specifically the failed one.",
							Ref:         ref(metav1.Time{}.OpenAPIModelName()),
						},
					},
				},
				Required: []string{"state"},
			},
		},
		Dependencies: []string{
			metav1.Time{}.OpenAPIModelName()},
	}
}

func schema_gpustack_api_worker_v1alpha1_DeviceInterfaceVirtualFunction(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "DeviceInterfaceVirtualFunction describes one SR-IOV virtual function of a physical function.\n\nIt is a type of its own rather than a nested DeviceInterface because SR-IOV nests exactly one level deep — a virtual function cannot itself be partitioned into virtual functions — so a self-referential shape would carry a level nothing can ever fill.\n\nWhat a VF shares with its parent is the UPSTREAM BRIDGE PATH — `pciRootId` (the outermost bridge, not a root complex) and `pciSwitches` — so those are read from the parent and not repeated here. A VF is its own PCI function with its own address, so that sharing is a claim about the path above both of them and nothing more. What can differ per VF is recorded: its own address, its own NUMA node and CPU list, and its own RDMA device and link verdict.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"name": {
						SchemaProps: spec.SchemaProps{
							Description: "Name is the kernel interface name of the virtual function.",
							Default:     "",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"pciBusId": {
						SchemaProps: spec.SchemaProps{
							Description: "PciBusID is the PCI bus ID of the virtual function, which is what distinguishes it from its siblings and from its parent.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"numaAffinity": {
						SchemaProps: spec.SchemaProps{
							Description: "NumaAffinity is the NUMA node the virtual function is attached to. Empty means unknown.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"cpuAffinity": {
						SchemaProps: spec.SchemaProps{
							Description: "CpuAffinity is the CPU cores close to the virtual function. Empty means unknown.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"mtu": {
						SchemaProps: spec.SchemaProps{
							Description: "MTU is the link MTU. Zero means it was not read. See DeviceInterface.MTU.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"up": {
						SchemaProps: spec.SchemaProps{
							Description: "Up reports the virtual function's operational state.",
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
					"rdma": {
						SchemaProps: spec.SchemaProps{
							Description: "RDMA reports that an RDMA device is bound to this virtual function.",
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
					"rdmaDevice": {
						SchemaProps: spec.SchemaProps{
							Description: "RDMADevice is the bound RDMA device's name. Empty when RDMA is false.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"link": {
						SchemaProps: spec.SchemaProps{
							Description: "Link is the result of verifying this virtual function's RDMA link. Nil when there is no RDMA link to verify.",
							Ref:         ref(v1alpha1.DeviceInterfaceLink{}.OpenAPIModelName()),
						},
					},
				},
				Required: []string{"name"},
			},
		},
		Dependencies: []string{
			v1alpha1.DeviceInterfaceLink{}.OpenAPIModelName()},
	}
}

func schema_gpustack_api_worker_v1alpha1_DeviceTopology(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "DeviceTopology describes the topology information of the device.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"pciBusId": {
						SchemaProps: spec.SchemaProps{
							Description: "PciBusID is the PCI bus ID of the device.",
							Default:     "",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"pciRootId": {
						SchemaProps: spec.SchemaProps{
							Description: "PciRootID is the address of the OUTERMOST PCI BRIDGE above the device, or the device's own address when no bridge sits above it.\n\nIt is NOT the root complex's identifier, despite the name. Two devices sharing this value reached it through one bridge subtree; they are not thereby behind the same switch, which is the tighter fact PciSwitches below carries. For a device attached directly to the root complex the value is the device itself, so equality there is an identity check rather than a same-root-complex claim.",
							Default:     "",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"pciClass": {
						SchemaProps: spec.SchemaProps{
							Description: "PciClass is the PCI class of the device.",
							Default:     "",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"numaAffinity": {
						SchemaProps: spec.SchemaProps{
							Description: "NumaAffinity is the NUMA node that the device is attached to. Empty means UNKNOWN and is never normalised to node 0 — that would report an affinity nobody read. The kernel's -1 \"no affinity\" sentinel and a reading that does not parse both arrive here as empty, so this field and the interface fields below carry the same contract.",
							Default:     "",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"cpuAffinity": {
						SchemaProps: spec.SchemaProps{
							Description: "CpuAffinity is the CPU cores that are close to the device.",
							Default:     "",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"roce": {
						SchemaProps: spec.SchemaProps{
							Description: "RoCE is the RoCE (RDMA over Converged Ethernet) network information of the device.",
							Ref:         ref(v1alpha1.DeviceEthernet{}.OpenAPIModelName()),
						},
					},
					"pciSwitches": {
						VendorExtensible: spec.VendorExtensible{
							Extensions: spec.Extensions{
								"x-kubernetes-list-type": "atomic",
							},
						},
						SchemaProps: spec.SchemaProps{
							Description: "PciSwitches is the upstream PCI bridge/switch path of the device, innermost first.\n\nTwo devices sharing the whole path sit behind the same switch, which is strictly tighter proximity than sharing the outermost bridge. PciRootID above is the OUTERMOST BRIDGE and not a switch: reporting equality there as switch-level proximity advertises closeness nobody measured, so the two fields are never read as the same claim.\n\nAbsent for a device with no PCI path at all, never an empty-but-present marker. Ordered by construction, so two consecutive reads of unchanged hardware are byte-identical.",
							Type:        []string{"array"},
							Items: &spec.SchemaOrArray{
								Schema: &spec.Schema{
									SchemaProps: spec.SchemaProps{
										Default: "",
										Type:    []string{"string"},
										Format:  "",
									},
								},
							},
						},
					},
				},
				Required: []string{"pciBusId", "pciRootId", "pciClass", "numaAffinity", "cpuAffinity"},
			},
		},
		Dependencies: []string{
			v1alpha1.DeviceEthernet{}.OpenAPIModelName()},
	}
}

func schema_gpustack_api_worker_v1alpha1_Devices(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "Devices is the schema for worker.gpustack.ai.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"kind": {
						SchemaProps: spec.SchemaProps{
							Description: "Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#types-kinds",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"apiVersion": {
						SchemaProps: spec.SchemaProps{
							Description: "APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#resources",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"metadata": {
						SchemaProps: spec.SchemaProps{
							Default: map[string]interface{}{},
							Ref:     ref(metav1.ObjectMeta{}.OpenAPIModelName()),
						},
					},
					"spec": {
						SchemaProps: spec.SchemaProps{
							Default: map[string]interface{}{},
							Ref:     ref(v1alpha1.DevicesSpec{}.OpenAPIModelName()),
						},
					},
					"status": {
						SchemaProps: spec.SchemaProps{
							Default: map[string]interface{}{},
							Ref:     ref(v1alpha1.DevicesStatus{}.OpenAPIModelName()),
						},
					},
				},
				Required: []string{"spec"},
			},
		},
		Dependencies: []string{
			v1alpha1.DevicesSpec{}.OpenAPIModelName(), v1alpha1.DevicesStatus{}.OpenAPIModelName(), metav1.ObjectMeta{}.OpenAPIModelName()},
	}
}

