func schema_gpustack_api_worker_v1alpha1_InstanceTypeDetail(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "InstanceTypeDetail is the observed hardware descriptor of an InstanceType, computed by the reconciler from the matched ResourceFlavor's notes and the pool's Devices ledger. It lives on the status side: because it embeds the accelerator's AcceleratorSlicedDetail (which holds a slice), it is not comparable and must never appear on the comparable, map-key InstanceTypeSpec.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"manufacturer": {
						SchemaProps: spec.SchemaProps{
							Description: "Manufacturer is the name of the InstanceType manufacturer.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"product": {
						SchemaProps: spec.SchemaProps{
							Description: "Product is the name of the InstanceType product.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"family": {
						SchemaProps: spec.SchemaProps{
							Description: "Family is the family of the InstanceType.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"physicalCores": {
						SchemaProps: spec.SchemaProps{
							Description: "PhysicalCores is the number of physical cores of the CPU, e.g. \"4\", \"8\".",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"threadsPerPhysicalCore": {
						SchemaProps: spec.SchemaProps{
							Description: "ThreadsPerPhysicalCore is the number of threads per physical core of the CPU, e.g. \"2\", \"4\".",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"logicalCores": {
						SchemaProps: spec.SchemaProps{
							Description: "LogicalCores is the number of logical cores of the CPU, e.g. \"8\", \"16\".",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"stepping": {
						SchemaProps: spec.SchemaProps{
							Description: "Stepping is the stepping of the CPU, e.g. \"0\", \"1\".",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"clockSpeed": {
						SchemaProps: spec.SchemaProps{
							Description: "ClockSpeed is the speed in Hz of the CPU, e.g. \"2000\"",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"maxClockSpeed": {
						SchemaProps: spec.SchemaProps{
							Description: "MaxClockSpeed is the maximum speed in Hz of the CPU, e.g. \"3000\"",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"cacheLine": {
						SchemaProps: spec.SchemaProps{
							Description: "CacheLine is the cache line size in bytes of the CPU, e.g. \"64\", \"128\".",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"cache": {
						SchemaProps: spec.SchemaProps{
							Description: "Cache describes the cache information of the CPU.",
							Default:     map[string]interface{}{},
							Ref:         ref(v1alpha1.InstanceTypeCPUCache{}.OpenAPIModelName()),
						},
					},
					"memory": {
						SchemaProps: spec.SchemaProps{
							Description: "Memory is the VRAM size of the accelerator, e.g. \"65535Mi\".",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"cores": {
						SchemaProps: spec.SchemaProps{
							Description: "Cores is the number of cores of the accelerator, e.g. \"128\", \"256\".",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"computeCapability": {
						SchemaProps: spec.SchemaProps{
							Description: "ComputeCapability is the compute capability of the accelerator, e.g. \"8.0\", \"7.0\".",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"runtimeVersion": {
						SchemaProps: spec.SchemaProps{
							Description: "RuntimeVersion is the accelerator runtime version observed across the pool, normalized to \"major.minor\" by the detectors, e.g. \"12.9\" for CUDA or \"8.2\" for CANN.\n\nIt is the MINIMUM over every node backing the accelerator group, not an arbitrary representative. One InstanceType spans every such node, and a driver rollout makes them disagree for as long as it runs; a container built against an older runtime runs on a newer driver but not the reverse, so the lowest version present is the one whose image every node can run. That is the property that matters, because a workload's image is fixed before admission chooses which node it lands on.\n\nAn empty value means NOTHING WAS OBSERVED - no synced flavor, or a pool with no accelerator group of its own - and is distinct from a pool whose nodes all report the same version. A consumer must not read it as a default.\n\nIT IS ALWAYS THE FIRST ELEMENT OF RuntimeVersions, which is where that invariant is maintained: both are assigned from one sorted list, so they cannot disagree by construction.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"runtimeVersions": {
						VendorExtensible: spec.VendorExtensible{
							Extensions: spec.Extensions{
								"x-kubernetes-list-type": "atomic",
							},
						},
						SchemaProps: spec.SchemaProps{
							Description: "RuntimeVersions is every distinct runtime version the pool's nodes report, ascending.\n\nIt exists so that a consumer can tell a pool that AGREES from one that does not, which the single value above cannot express. A driver rollout makes the nodes disagree for as long as it runs, and a workload built from the minimum needs to be able to say what it skipped.\n\nA consumer reads disagreement as len() > 1 and the skipped versions as the tail. That is a length comparison rather than a second copy of the aggregation, which is the whole reason this is published instead of being recomputed from the Devices ledger downstream.",
							Type:        []string{"array"},
							Items: &spec.SchemaOrArray{
								Schema: &spec.Schema{
									SchemaProps: spec.SchemaProps{
										Default: "",
										Type:    []string{"string"},
										Format:  "",
									},
								},
							},
						},
					},
					"slicedDetail": {
						SchemaProps: spec.SchemaProps{
							Description: "SlicedDetail is the pool's aggregated slicing capability for this accelerator group.",
							Default:     map[string]interface{}{},
							Ref:         ref(v1alpha1.AcceleratorSlicedDetail{}.OpenAPIModelName()),
						},
					},
					"cpu": {
						SchemaProps: spec.SchemaProps{
							Description: "CPU describes the CPU information of the accelerator.",
							Default:     map[string]interface{}{},
							Ref:         ref(v1alpha1.InstanceTypeAcceleratorCPU{}.OpenAPIModelName()),
						},
					},
				},
			},
		},
		Dependencies: []string{
			v1alpha1.AcceleratorSlicedDetail{}.OpenAPIModelName(), v1alpha1.InstanceTypeAcceleratorCPU{}.OpenAPIModelName(), v1alpha1.InstanceTypeCPUCache{}.OpenAPIModelName()},
	}
}

