func schema_gpustack_api_worker_v1alpha1_KVCacheBackendEndpoint(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "KVCacheBackendEndpoint is one named address of a backend. The same type serves the external branch's input and the status's output, so a reader learns one shape.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"address": {
						SchemaProps: spec.SchemaProps{
							Description: "Address is host:port.\n\n259 and not 253: the bound is on host:port, and the host alone may be a DNS subdomain of the full 253 characters, which leaves room for a colon and a five-digit port. At 253 the schema refused an address the webhook's own host:port rule accepts.",
							Default:     "",
							MaxLength:   ptr.To[int64](259),
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"name": {
						SchemaProps: spec.SchemaProps{
							Description: "Name says who the address is for, and the two readers want different things. Client is what an inference engine connects to. Admin is the port serving the Prometheus exposition and the HTTP admin API both, which is what THIS OPERATOR reads. A consumer handed the wrong one fails at connect time with nothing to point at, which is why the distinction is carried in the API rather than left to a convention.",
							Default:     "",
							Type:        []string{"string"},
							Format:      "",
						},
					},
				},
				Required: []string{"address", "name"},
			},
		},
	}
}

func schema_gpustack_api_worker_v1alpha1_KVCacheBackendExternal(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "KVCacheBackendExternal is a backend this operator does not run.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"endpoints": {
						VendorExtensible: spec.VendorExtensible{
							Extensions: spec.Extensions{
								"x-kubernetes-list-map-keys": []interface{}{
									"name",
								},
								"x-kubernetes-list-type": "map",
							},
						},
						SchemaProps: spec.SchemaProps{
							Description: "Endpoints are the addresses of a backend somebody else runs, one entry per named role. Both roles are required here, and for the same reason they are two entries and not one string: this operator reads the Admin address and publishes the Client address, so an external backend that named only one leaves either the scrape or every engine with nothing to point at.\n\nIt is a list rather than a single address so that a multi-leader backend needs no API change to describe.",
							MinItems:    ptr.To[int64](1),
							Type:        []string{"array"},
							Items: &spec.SchemaOrArray{
								Schema: &spec.Schema{
									SchemaProps: spec.SchemaProps{
										Default: map[string]interface{}{},
										Ref:     ref(v1alpha1.KVCacheBackendEndpoint{}.OpenAPIModelName()),
									},
								},
							},
						},
					},
				},
				Required: []string{"endpoints"},
			},
		},
		Dependencies: []string{
			v1alpha1.KVCacheBackendEndpoint{}.OpenAPIModelName()},
	}
}

func schema_gpustack_api_worker_v1alpha1_KVCacheBackendLeader(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "KVCacheBackendLeader is the leader process: how many of it, how it places new writes, and the escape hatch for flags this API does not enumerate.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"replicas": {
						SchemaProps: spec.SchemaProps{
							Description: "Replicas is how many leader processes run. One, and only one, in this scope: electing a leader among several needs a backend store this scope does not enter, and the webhook refuses anything else while naming that follow-on rather than silently running one anyway.",
							Minimum:     ptr.To[float64](1),
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"allocationStrategy": {
						SchemaProps: spec.SchemaProps{
							Description: "AllocationStrategy is how the leader picks which member takes a new write. Random spreads them; FreeRatioFirst biases toward the emptier member.\n\nThe enum is deliberately the two that any pooled store would have, rather than every value the current artifact's flag accepts: the others it accepts are specific to one medium or one locality model, are reachable through ExtraArgs for anyone who needs them, and would otherwise fix this API to one implementation's vocabulary. Widening the enum later is not a breaking change.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"multiTenancy": {
						SchemaProps: spec.SchemaProps{
							Description: "MultiTenancy turns on the leader's per-tenant quota ledger and the tenant-scoped shard index behind it. Off, every request falls into one default tenant and the index degrades to a plain key hash, so two callers using different tenant names read each other's cache.\n\nIt is a FIELD rather than an extraArgs entry because another API validates against it: a KVCachePool is refused when its backend has no ledger to write quota into. A webhook reading an unschema'd string — \"true\", \"1\", \"True\" — would be judging a value domain that belongs to whoever typed it.\n\nA plain bool, not a pointer, because unset and false mean the same thing here: no ledger. Unset renders NO flag rather than an explicit false, so a backend that never asked for this runs the command line it ran before the field existed.",
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
					"extraArgs": {
						SchemaProps: spec.SchemaProps{
							Description: "ExtraArgs passes flags this API does not enumerate straight through to the leader, after the derived ones. A key that collides with a flag rendered from a field above is refused at admission, because two sources for one flag make the rendered command ambiguous.\n\nEVERY VALUE HERE IS WORLD-READABLE, on three paths and not one. It is stored verbatim on THIS object, which is cluster-scoped, so reading it needs no access to any workload; it is then rendered into the leader container's argv as -key=value, which exposes it again to anyone who can read the Pod or the Deployment carrying it. It stays readable for the life of the object. A credential does not belong here. This operator renders no flag that carries one, so this field is the only way one arrives.",
							Type:        []string{"object"},
							AdditionalProperties: &spec.SchemaOrBool{
								Allows: true,
								Schema: &spec.Schema{
									SchemaProps: spec.SchemaProps{
										Default: "",
										Type:    []string{"string"},
										Format:  "",
									},
								},
							},
						},
					},
					"offload": {
						SchemaProps: spec.SchemaProps{
							Description: "Offload turns on writing evicted keys to the members' local disk tier. It is the leader's half of a pair: the other half is members[].localDisk, which says where on each node those bytes go, and admission refuses either half alone because the store degrades on both mismatches without reporting either.",
							Ref:         ref(v1alpha1.KVCacheBackendLeaderOffload{}.OpenAPIModelName()),
						},
					},
				},
			},
		},
		Dependencies: []string{
			v1alpha1.KVCacheBackendLeaderOffload{}.OpenAPIModelName()},
	}
}

func schema_gpustack_api_worker_v1alpha1_KVCacheBackendLeaderOffload(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "KVCacheBackendLeaderOffload turns the local disk tier on, leader side.\n\nBoth settings are the leader's, and Enabled gates the feature outright: the store ANDs its eviction-time and promotion behavior with it, and every offload entry point returns early without it. A tier configured on the member alone is inert, which is why admission requires the two halves together rather than letting one render on its own.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"enabled": {
						SchemaProps: spec.SchemaProps{
							Description: "Enabled turns on offloading to the members' local disks.\n\nA plain bool, not a pointer, because unset and false mean the same thing: no offloading. Unset renders NO flag rather than an explicit false, so a backend that never asked for this runs the command line it ran before the field existed.",
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
					"onEvict": {
						SchemaProps: spec.SchemaProps{
							Description: "OnEvict defers the write to disk from the moment a key is stored to the moment it is evicted, so a key that is never evicted is never written to disk.\n\nIt REQUIRES Enabled. The store ANDs the two, so setting this alone is accepted, echoed back in the leader's own startup log, and then does nothing — which is why admission refuses it rather than rendering a flag that reads as taken.",
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
				},
			},
		},
	}
}

